@tool
def list_tables() -> str:
    try:
        pool = _get_pool()
        with pool.acquire() as conn:
            with conn.cursor() as cur:
                # Clean up leftover scratch tables (TMP_ prefix) from earlier sessions
                # so they don't clutter the listing. PURGE skips the recycle bin.
                cur.execute("SELECT table_name FROM user_tables WHERE table_name LIKE 'TMP\\_%' ESCAPE '\\'")
                for (tmp_name,) in cur.fetchall():
                    cur.execute(f'DROP TABLE "{tmp_name}" PURGE')
                cur.execute("\n                    SELECT table_name, 'TABLE' AS object_type FROM user_tables\n                    UNION ALL\n                    SELECT view_name, 'VIEW' FROM user_views\n                    ORDER BY 1\n                    ")
                rows = cur.fetchall()
        if not rows:
            return 'No tables or views found for this account.'
        return '\n'.join((f'{name} ({kind})' for name, kind in rows))
    except Exception as e:
        return f'Error listing tables: {e}'
